@Slf4j
@Service("cmbcDownloadBillService")
public class CMBCDownloadBillServiceImpl implements DownloadBillService {

    private String applyBillServiceName = "minsheng-bill-samAsyncElectronicReceiptApply";
    private String downloadBillServiceName = "minsheng-bill-samAsyncElectronicReceiptQry";

    @Value("${downloadBill.gateway.url}")
    private String gatewayUrl;

    @Value("${cmbc.signCode}")
    private String signCode;

    @Value("${cmbc.merchantNo}")
    private String merchantNo;

    @Override
    public String downloadBill(FileHandleTaskDo fileHandleTaskDo) {
        String response = null;
        BufferedWriter writer = null;
        try {

            response = this.billDownload(fileHandleTaskDo);
            if (null != response && !response.equals("")) {
                String filePath = fileHandleTaskDo.getSourceFilePath();
                String fileName = merchantNo + "_" + fileHandleTaskDo.getSourceFileName();

                File file = new File(filePath);
                if (file.isDirectory()) {
                    writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(filePath + "/" + fileName), Charset.forName("utf-8")));
                    writer.write("\ufeff");
                    writer.write(response);
                    writer.newLine();
                    writer.flush();
                    log.info("文件下载存放路径:" + file.getPath());
                } else {
                    log.info("该路径不是文件夹");
                    file.mkdirs();
                    log.info("创建文件夹");
                    writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(filePath + "/" + fileName), Charset.forName("utf-8")));
                    writer.write("\ufeff");
                    writer.write(response);
                    writer.newLine();
                    writer.flush();
                    log.info("文件下载存放路径:" + file.getPath());
                }
                return fileName;
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            if (null != writer) {
                try {
                    writer.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        return null;
    }

    @Override
    public String preDownload(FileHandleTaskDo fileHandleTaskDo) {
        return this.billApply(fileHandleTaskDo);
    }

    /**
     * 申请下载民生对账单
     *
     * @param fileHandleTaskDo
     * @return
     */
    public String billApply(FileHandleTaskDo fileHandleTaskDo) {

        JSONObject gateway = new JSONObject();
        gateway.put("merchantNo", signCode);
        gateway.put("platformId", merchantNo);
        gateway.put("merSerialNo", org.apache.commons.lang3.StringUtils.leftPad("CMBCBill" + System.currentTimeMillis(), 32, "0"));
        gateway.put("saTxDt1", DateUtil.dateToString(DateUtil.plusDays(fileHandleTaskDo.getHandleDt(), -1)));
        gateway.put("saTxDt2", DateUtil.dateToString(fileHandleTaskDo.getHandleDt()));

        log.info("申请下载CMBC对账文件调用网关加签接口，请求参数: jsonObject->" + gateway);
        String billContentResponse = HttpUtil.postJsonBody(gatewayUrl + applyBillServiceName, gateway.toJSONString());
        log.info("申请下载CMBC对账文件网关返回的信息->" + billContentResponse);

        String errMsg = "";
        // 请求下载内容是否为空
        if (billContentResponse == null) {
            errMsg = ErrorCode.GATWAY_DOWNLOAD_BILL_CONTENT_EMPTY.getMessage() + ",billSignContent="+billContentResponse;
            log.error(errMsg);
            throw new BusinessException(ErrorCode.GATWAY_DOWNLOAD_BILL_CONTENT_EMPTY);
        }

        JSONObject respObj = JSON.parseObject(billContentResponse);
        //成功-S，失败-E
        String returnType = respObj.getString("returnType");
        //成功：AAAAAA   失败：ERROR_00001
//        String returnCode = respObj.getString("returnCode");
        String returnMsg = respObj.getString("returnMsg");
        if ("S".equals(returnType)) {
            return respObj.getString("askSerialNoDownload");
        } else if ("E".equals(returnType) && StringUtils.isNotEmpty(returnMsg) && returnMsg.contains("查询无数据")) {
            return "no data";
        }
        log.error("申请下载民生银行对账单接口失败，{}", returnMsg);
        throw new BusinessException(ErrorCode.GATWAY_DOWNLOAD_BILL_CONTENT_EMPTY);
    }

